        if(this.getBreed() != null && this.getBreed().getBroilerGuideList()!=null) {
          BroilerGuide dg =
                  this.getBreed().getBroilerGuideList().stream()
						  .filter(x-> x.getDayNumber() == this.getDayNumber() -1).findFirst().orElse(null);
          if (dg != null){
            return this.getWeight() - dg.getWeight() ;
