        }
        return 0;

entity.decimal:


if(this.getBreed() != null && this.getBreed().getBroilerGuideList()!=null) {
    return BigDecimal.valueOf(this.getBreed().getBroilerGuideList().stream()
            .filter(x-> x.getDayNumber() <= this.getDayNumber())
            .mapToDouble(d-> d.getWeight()).average().orElse(0));
}
return BigDecimal.ZERO;

entity.integer:


if(this.getBreed() != null && this.getBreed().getBroilerGuideList()!=null) {
    return this.getBreed().getBroilerGuideList().stream()
           .filter(x-> x.getDayNumber() <= this.getDayNumber())
           .mapToInt(d-> d.getDailyConsumption()).sum();
}
return 0;
